//! A temporal evolution records and returns long relationship objects.

use andromeda_test_suite::{attribute_matcher::any_attribute, broker, evolution_matcher::has_evolution, namespace::Namespace, outcome::Upserted};
use googletest::prelude::*;
use ngsi_ld::{
    http::headers::Accept,
    model::{NgsiLdMediaType, Relationship, evolution::TemporalEntity},
};

/// Pins: Create Temporal Evolution of a Relationship whose instances name URNs of over 6,000 and over 2,048 octets
/// answers 201, and both instances read back with their objects unchanged
/// Clause: 5.6.11, 5.7.3, 4.6.2
#[gtest]
#[tokio::test]
async fn n_tmp_ups_9006_a_temporal_evolution_records_and_returns_long_relationship_objects() -> Result<()> {
    let namespace = Namespace::fresh();
    let broker = broker::front()?;
    let long_reference_history_id = namespace.urn("LongReference", "history")?;
    let long_reference_type = namespace.entity_type("LongReference")?;
    let stop_p55h7qol8di08sr6ohcho7y980jr24l2uw9ygw3p_id = namespace.urn("Stop", "")?;
    let stop_k2xv6mpk3o9bpjjepm9t6cf0le4dut01sdiapi6e_id = namespace.urn("Stop", "")?;
    let long_reference_history_evolution = TemporalEntity::builder()
        .id(long_reference_history_id.clone())
        .entity_type(long_reference_type)
        .relationship(
            "link",
            Relationship::builder(stop_p55h7qol8di08sr6ohcho7y980jr24l2uw9ygw3p_id.clone()).observed_at("2026-01-01T00:00:00Z".parse()?),
        )
        .relationship(
            "link",
            Relationship::builder(stop_k2xv6mpk3o9bpjjepm9t6cf0le4dut01sdiapi6e_id.clone()).observed_at("2026-01-01T00:01:00Z".parse()?),
        )
        .build()?;
    broker.temporal().create_or_update(&long_reference_history_evolution).send().await?.created()?;
    let retrieved = broker
        .with_accept(Accept::new(NgsiLdMediaType::Json))
        .temporal()
        .retrieve(&long_reference_history_id)
        .send()
        .await?;
    let evolution = retrieved.body();
    expect_that!(
        evolution,
        has_evolution(
            "link",
            all!(
                len(eq(2)),
                contains(any_attribute().object(stop_p55h7qol8di08sr6ohcho7y980jr24l2uw9ygw3p_id.clone())),
                contains(any_attribute().object(stop_k2xv6mpk3o9bpjjepm9t6cf0le4dut01sdiapi6e_id.clone()))
            )
        )
    );
    Ok(())
}
